// The document arrives as markdown. Email it as text: a task form is meant to be read on a
// phone and answered at a desk, and HTML would only obscure the frontmatter that carries the
// fields somebody has to fill in.
const d = $input.first().json.body ?? $input.first().json;
const title = d.title || d.filename || 'Reckons.AI task';
const graph = d.graph ? ` [${d.graph}]` : '';

return [{
  json: {
    subject: `Task needs authorising${graph}: ${title}`,
    body: [
      d.markdown || '(no document body)',
      '',
      '--',
      'Fill in `effect` and `done_when` in the file, then run:',
      '  npx tsx scripts/agent/tasks-import.ts',
      '',
      'The answers arrive as PENDING facts. Accepting them in Reckons.AI is what',
      'authorises the task; this email does not.',
    ].join('\n'),
    filename: d.filename,
    task: d.task,
  },
}];
